insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-jazz-trivia',
  'Jazz Trivia: From New Orleans to Bebop',
  'Eight questions on the artists and styles that shaped jazz, from the birth of swing in New Orleans to Coltrane''s spiritual suites.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'music'),
  '[{"id":"q1","question":"In which American city was jazz born in the early 20th century?","options":[{"id":"a","text":"Chicago","is_correct":false},{"id":"b","text":"New Orleans","is_correct":true},{"id":"c","text":"New York","is_correct":false},{"id":"d","text":"Kansas City","is_correct":false}],"explanation":"Jazz emerged in New Orleans from a blend of blues, ragtime and brass-band music."},{"id":"q2","question":"Which trumpeter and singer, nicknamed ''Satchmo'', became jazz''s first great soloist?","options":[{"id":"a","text":"Louis Armstrong","is_correct":true},{"id":"b","text":"Miles Davis","is_correct":false},{"id":"c","text":"Dizzy Gillespie","is_correct":false},{"id":"d","text":"Wynton Marsalis","is_correct":false}],"explanation":"Armstrong''s solos and vocals set the template for jazz improvisation in the 1920s."},{"id":"q3","question":"Which singer, famous for her scat singing, was known as the ''First Lady of Song''?","options":[{"id":"a","text":"Billie Holiday","is_correct":false},{"id":"b","text":"Sarah Vaughan","is_correct":false},{"id":"c","text":"Nina Simone","is_correct":false},{"id":"d","text":"Ella Fitzgerald","is_correct":true}],"explanation":"Ella Fitzgerald''s scat improvisations and songbook albums made her the ''First Lady of Song''."},{"id":"q4","question":"Which 1959 Miles Davis album became the best-selling jazz record of all time?","options":[{"id":"a","text":"Kind of Blue","is_correct":true},{"id":"b","text":"Bitches Brew","is_correct":false},{"id":"c","text":"Sketches of Spain","is_correct":false},{"id":"d","text":"Birth of the Cool","is_correct":false}],"explanation":"Kind of Blue (1959), with John Coltrane and Bill Evans, is the best-selling jazz album ever."},{"id":"q5","question":"Which 1965 John Coltrane album is a four-part suite dedicated to spirituality?","options":[{"id":"a","text":"Giant Steps","is_correct":false},{"id":"b","text":"Blue Train","is_correct":false},{"id":"c","text":"A Love Supreme","is_correct":true},{"id":"d","text":"My Favorite Things","is_correct":false}],"explanation":"A Love Supreme (1965) is Coltrane''s devotional suite in four movements."},{"id":"q6","question":"Which jazz style did Charlie Parker and Dizzy Gillespie pioneer in the 1940s?","options":[{"id":"a","text":"Swing","is_correct":false},{"id":"b","text":"Bebop","is_correct":true},{"id":"c","text":"Ragtime","is_correct":false},{"id":"d","text":"Fusion","is_correct":false}],"explanation":"Bebop shifted jazz from dance halls to small combos playing fast, complex solos."},{"id":"q7","question":"Which clarinetist and bandleader was crowned the ''King of Swing'' in the 1930s?","options":[{"id":"a","text":"Duke Ellington","is_correct":false},{"id":"b","text":"Count Basie","is_correct":false},{"id":"c","text":"Glenn Miller","is_correct":false},{"id":"d","text":"Benny Goodman","is_correct":true}],"explanation":"Benny Goodman''s orchestra carried swing to national fame in the 1930s."},{"id":"q8","question":"What is the name of the practice at the heart of jazz, where musicians create melodies on the spot?","options":[{"id":"a","text":"Improvisation","is_correct":true},{"id":"b","text":"Transcription","is_correct":false},{"id":"c","text":"Harmonization","is_correct":false},{"id":"d","text":"Orchestration","is_correct":false}],"explanation":"Improvisation lets jazz musicians compose new lines in real time over a song''s harmony."}]'::jsonb,
  null,
  array['music', 'trivia', 'jazz', 'musicians', 'music history']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
