values (
  'es-trivia-jazz',
  'Trivia de jazz: de Nueva Orleans al bebop',
  'Ocho preguntas sobre los artistas y estilos que moldearon el jazz, del nacimiento del swing en Nueva Orleans a las suites de Coltrane.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'music'),
  '[{"id":"q1","question":"¿En qué ciudad de Estados Unidos nació el jazz a comienzos del siglo XX?","options":[{"id":"a","text":"Chicago","is_correct":false},{"id":"b","text":"Nueva Orleans","is_correct":true},{"id":"c","text":"Nueva York","is_correct":false},{"id":"d","text":"Kansas City","is_correct":false}],"explanation":"El jazz surgió en Nueva Orleans de la mezcla del blues, el ragtime y las bandas de viento."},{"id":"q2","question":"¿Qué trompetista y cantante, apodado «Satchmo», se convirtió en el primer gran solista del jazz?","options":[{"id":"a","text":"Louis Armstrong","is_correct":true},{"id":"b","text":"Miles Davis","is_correct":false},{"id":"c","text":"Dizzy Gillespie","is_correct":false},{"id":"d","text":"Wynton Marsalis","is_correct":false}],"explanation":"Los solos y la voz de Armstrong marcaron la pauta de la improvisación jazzística en los años veinte."},{"id":"q3","question":"¿Qué cantante, famosa por su scat, era conocida como la «Primera Dama de la Canción»?","options":[{"id":"a","text":"Billie Holiday","is_correct":false},{"id":"b","text":"Sarah Vaughan","is_correct":false},{"id":"c","text":"Nina Simone","is_correct":false},{"id":"d","text":"Ella Fitzgerald","is_correct":true}],"explanation":"El scat y los álbumes de cancioneros de Ella Fitzgerald la convirtieron en la «Primera Dama de la Canción»."},{"id":"q4","question":"¿Qué álbum de Miles Davis, de 1959, se convirtió en el disco de jazz más vendido de la historia?","options":[{"id":"a","text":"Kind of Blue","is_correct":true},{"id":"b","text":"Bitches Brew","is_correct":false},{"id":"c","text":"Sketches of Spain","is_correct":false},{"id":"d","text":"Birth of the Cool","is_correct":false}],"explanation":"Kind of Blue (1959), con John Coltrane y Bill Evans, es el álbum de jazz más vendido."},{"id":"q5","question":"¿Qué álbum de John Coltrane, de 1965, es una suite en cuatro partes dedicada a la espiritualidad?","options":[{"id":"a","text":"Giant Steps","is_correct":false},{"id":"b","text":"Blue Train","is_correct":false},{"id":"c","text":"A Love Supreme","is_correct":true},{"id":"d","text":"My Favorite Things","is_correct":false}],"explanation":"A Love Supreme (1965) es la suite devocional de Coltrane en cuatro movimientos."},{"id":"q6","question":"¿Qué estilo del jazz impulsaron Charlie Parker y Dizzy Gillespie en los años cuarenta?","options":[{"id":"a","text":"El swing","is_correct":false},{"id":"b","text":"El bebop","is_correct":true},{"id":"c","text":"El ragtime","is_correct":false},{"id":"d","text":"La fusión","is_correct":false}],"explanation":"El bebop sacó al jazz de los salones de baile hacia pequeñas formaciones de solos rápidos y complejos."},{"id":"q7","question":"¿Qué clarinetista y director de orquesta fue coronado «rey del swing» en los años treinta?","options":[{"id":"a","text":"Duke Ellington","is_correct":false},{"id":"b","text":"Count Basie","is_correct":false},{"id":"c","text":"Glenn Miller","is_correct":false},{"id":"d","text":"Benny Goodman","is_correct":true}],"explanation":"La orquesta de Benny Goodman llevó el swing a la fama nacional en los años treinta."},{"id":"q8","question":"¿Cómo se llama la práctica esencial del jazz que consiste en crear melodías en el momento?","options":[{"id":"a","text":"La improvisación","is_correct":true},{"id":"b","text":"La transcripción","is_correct":false},{"id":"c","text":"La armonización","is_correct":false},{"id":"d","text":"La orquestación","is_correct":false}],"explanation":"La improvisación permite crear frases nuevas en tiempo real sobre la armonía de un tema."}]'::jsonb,
  null,
  array['música', 'trivia', 'jazz', 'músicos', 'historia de la música']::text[],
  3,
  'published',
  false,
  false,
  now()
)
