insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-opera-trivia',
  'Opera Trivia: Voices, Arias and Great Composers',
  'Eight questions on four centuries of opera, from Monteverdi''s first masterpiece to the stages of La Scala and the Met.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'music'),
  '[{"id":"q1","question":"Which composer''s L''Orfeo (1607) is considered the first great opera?","options":[{"id":"a","text":"Jacopo Peri","is_correct":false},{"id":"b","text":"George Frideric Handel","is_correct":false},{"id":"c","text":"Claudio Monteverdi","is_correct":true},{"id":"d","text":"Christoph Willibald Gluck","is_correct":false}],"explanation":"Monteverdi''s L''Orfeo, premiered in Mantua in 1607, established opera as an art form."},{"id":"q2","question":"Which Mozart opera tells how a servant outsmarts his master on a wedding day?","options":[{"id":"a","text":"Don Giovanni","is_correct":false},{"id":"b","text":"Le nozze di Figaro","is_correct":true},{"id":"c","text":"Die Zauberflöte","is_correct":false},{"id":"d","text":"Così fan tutte","is_correct":false}],"explanation":"Le nozze di Figaro (1786) follows Figaro''s tricks to marry Susanna despite his count''s schemes."},{"id":"q3","question":"Which Italian composer wrote Aida, Rigoletto and La traviata?","options":[{"id":"a","text":"Giacomo Puccini","is_correct":false},{"id":"b","text":"Gioachino Rossini","is_correct":false},{"id":"c","text":"Vincenzo Bellini","is_correct":false},{"id":"d","text":"Giuseppe Verdi","is_correct":true}],"explanation":"Verdi dominated 19th-century Italian opera with those three landmarks."},{"id":"q4","question":"Which composer wrote the four-opera cycle Der Ring des Nibelungen and had a theater built in Bayreuth?","options":[{"id":"a","text":"Richard Wagner","is_correct":true},{"id":"b","text":"Richard Strauss","is_correct":false},{"id":"c","text":"Carl Maria von Weber","is_correct":false},{"id":"d","text":"Robert Schumann","is_correct":false}],"explanation":"Wagner composed the Ring cycle over about 26 years and opened his Bayreuth Festspielhaus in 1876."},{"id":"q5","question":"Which Puccini opera follows the doomed romance of a Japanese geisha?","options":[{"id":"a","text":"Tosca","is_correct":false},{"id":"b","text":"La bohème","is_correct":false},{"id":"c","text":"Madama Butterfly","is_correct":true},{"id":"d","text":"Turandot","is_correct":false}],"explanation":"Madama Butterfly (1904) tells of Cio-Cio-San, abandoned by an American naval officer."},{"id":"q6","question":"In opera, what is an ''aria''?","options":[{"id":"a","text":"A solo song that expresses a character''s feelings","is_correct":true},{"id":"b","text":"An instrumental passage for the orchestra","is_correct":false},{"id":"c","text":"A spoken dialogue between acts","is_correct":false},{"id":"d","text":"A group dance scene","is_correct":false}],"explanation":"An aria is a self-contained solo where a character stops the action to express emotion."},{"id":"q7","question":"The ''bel canto'' style, associated with Rossini, Donizetti and Bellini, translates from Italian as what?","options":[{"id":"a","text":"''Grand opera''","is_correct":false},{"id":"b","text":"''Golden voice''","is_correct":false},{"id":"c","text":"''Sweet melody''","is_correct":false},{"id":"d","text":"''Beautiful singing''","is_correct":true}],"explanation":"Bel canto means ''beautiful singing'': long vocal lines demanding agility and control."},{"id":"q8","question":"In which two cities are La Scala and the Metropolitan Opera, respectively?","options":[{"id":"a","text":"Rome and London","is_correct":false},{"id":"b","text":"Milan and New York","is_correct":true},{"id":"c","text":"Naples and Chicago","is_correct":false},{"id":"d","text":"Venice and Boston","is_correct":false}],"explanation":"Milan''s Teatro alla Scala opened in 1778; the Met in New York in 1883."}]'::jsonb,
  null,
  array['music', 'trivia', 'opera', 'classical music', 'composers']::text[],
  4,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
