values (
  'es-trivia-opera',
  'Trivia de ópera: voces, arias y grandes compositores',
  'Ocho preguntas sobre cuatro siglos de ópera, de la primera obra maestra de Monteverdi a los escenarios de La Scala y el Met.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'music'),
  '[{"id":"q1","question":"¿Qué compositor firmó L''Orfeo (1607), considerada la primera gran ópera?","options":[{"id":"a","text":"Jacopo Peri","is_correct":false},{"id":"b","text":"Georg Friedrich Händel","is_correct":false},{"id":"c","text":"Claudio Monteverdi","is_correct":true},{"id":"d","text":"Christoph Willibald Gluck","is_correct":false}],"explanation":"L''Orfeo de Monteverdi, estrenada en Mantua en 1607, estableció la ópera como forma artística."},{"id":"q2","question":"¿Qué ópera de Mozart cuenta cómo un criado burla a su amo el día de una boda?","options":[{"id":"a","text":"Don Giovanni","is_correct":false},{"id":"b","text":"Le nozze di Figaro","is_correct":true},{"id":"c","text":"Die Zauberflöte","is_correct":false},{"id":"d","text":"Così fan tutte","is_correct":false}],"explanation":"Le nozze di Figaro (1786) narra las artimañas de Fígaro para casarse con Susana."},{"id":"q3","question":"¿Qué compositor italiano escribió Aida, Rigoletto y La traviata?","options":[{"id":"a","text":"Giacomo Puccini","is_correct":false},{"id":"b","text":"Gioachino Rossini","is_correct":false},{"id":"c","text":"Vincenzo Bellini","is_correct":false},{"id":"d","text":"Giuseppe Verdi","is_correct":true}],"explanation":"Verdi dominó la ópera italiana del siglo XIX con esos tres hitos."},{"id":"q4","question":"¿Qué compositor escribió la tetralogía Der Ring des Nibelungen y mandó construir su teatro en Bayreuth?","options":[{"id":"a","text":"Richard Wagner","is_correct":true},{"id":"b","text":"Richard Strauss","is_correct":false},{"id":"c","text":"Carl Maria von Weber","is_correct":false},{"id":"d","text":"Robert Schumann","is_correct":false}],"explanation":"Wagner compuso el Anillo durante unos 26 años e inauguró su Festspielhaus de Bayreuth en 1876."},{"id":"q5","question":"¿Qué ópera de Puccini narra el romance condenado de una geisha japonesa?","options":[{"id":"a","text":"Tosca","is_correct":false},{"id":"b","text":"La bohème","is_correct":false},{"id":"c","text":"Madama Butterfly","is_correct":true},{"id":"d","text":"Turandot","is_correct":false}],"explanation":"Madama Butterfly (1904) cuenta la historia de Cio-Cio-San, abandonada por un oficial estadounidense."},{"id":"q6","question":"En la ópera, ¿qué es un «aria»?","options":[{"id":"a","text":"Una canción solista que expresa los sentimientos de un personaje","is_correct":true},{"id":"b","text":"Un pasaje instrumental para la orquesta","is_correct":false},{"id":"c","text":"Un diálogo hablado entre actos","is_correct":false},{"id":"d","text":"Una escena de baile grupal","is_correct":false}],"explanation":"Un aria es un solo cerrado donde el personaje detiene la acción para expresar emoción."},{"id":"q7","question":"El estilo «bel canto», asociado a Rossini, Donizetti y Bellini, significa en italiano…","options":[{"id":"a","text":"«Gran ópera»","is_correct":false},{"id":"b","text":"«Voz dorada»","is_correct":false},{"id":"c","text":"«Dulce melodía»","is_correct":false},{"id":"d","text":"«Canto bello»","is_correct":true}],"explanation":"Bel canto significa «canto bello»: líneas vocales largas que exigen agilidad y control."},{"id":"q8","question":"¿En qué dos ciudades están, respectivamente, La Scala y el Metropolitan Opera?","options":[{"id":"a","text":"Roma y Londres","is_correct":false},{"id":"b","text":"Milán y Nueva York","is_correct":true},{"id":"c","text":"Nápoles y Chicago","is_correct":false},{"id":"d","text":"Venecia y Boston","is_correct":false}],"explanation":"El Teatro alla Scala de Milán abrió en 1778; el Met de Nueva York en 1883."}]'::jsonb,
  null,
  array['música', 'trivia', 'ópera', 'música clásica', 'compositores']::text[],
  4,
  'published',
  false,
  false,
