insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-reggaeton-trivia',
  'Reggaetón Trivia: From the Underground to Global Pop',
  'Eight questions on the genre born in Puerto Rico''s underground scene that conquered the world, from the dembow to ''Despacito''.',
  'trivia',
  'easy',
  'en',
  (select id from public.categories where slug = 'music'),
  '[{"id":"q1","question":"Reggaetón''s signature rhythm, the ''dembow'', takes its name from which Shabba Ranks song?","options":[{"id":"a","text":"''Dem Bow''","is_correct":true},{"id":"b","text":"''Ting-A-Ling''","is_correct":false},{"id":"c","text":"''Mr. Loverman''","is_correct":false},{"id":"d","text":"''Housecall''","is_correct":false}],"explanation":"Shabba Ranks'' 1990 dancehall track ''Dem Bow'' supplied the drum pattern reggaetón still uses."},{"id":"q2","question":"In which Caribbean island did reggaetón take shape in the 1990s underground scene?","options":[{"id":"a","text":"Jamaica","is_correct":false},{"id":"b","text":"Cuba","is_correct":false},{"id":"c","text":"Puerto Rico","is_correct":true},{"id":"d","text":"Dominican Republic","is_correct":false}],"explanation":"Reggaetón crystallized in San Juan''s underground and club scene during the 1990s."},{"id":"q3","question":"Which country is credited with the earlier ''reggae en español'' scene that fed into reggaetón?","options":[{"id":"a","text":"Panama","is_correct":true},{"id":"b","text":"Colombia","is_correct":false},{"id":"c","text":"Venezuela","is_correct":false},{"id":"d","text":"Mexico","is_correct":false}],"explanation":"Panamanian artists like El General recorded Spanish-language reggae from the late 1980s."},{"id":"q4","question":"Which Daddy Yankee song broke reggaetón into the global mainstream in 2004?","options":[{"id":"a","text":"''Despacito''","is_correct":false},{"id":"b","text":"''Lo Que Pasó, Pasó''","is_correct":false},{"id":"c","text":"''Rompe''","is_correct":false},{"id":"d","text":"''Gasolina''","is_correct":true}],"explanation":"''Gasolina'', from the 2004 album Barrio Fino, was reggaetón''s first worldwide smash."},{"id":"q5","question":"Which Puerto Rican artist scored hits with ''Danza Kuduro'' and ''Dale Don Dale''?","options":[{"id":"a","text":"Don Omar","is_correct":true},{"id":"b","text":"Wisin","is_correct":false},{"id":"c","text":"Tego Calderón","is_correct":false},{"id":"d","text":"Nicky Jam","is_correct":false}],"explanation":"Don Omar, dubbed ''El Rey'', took ''Danza Kuduro'' to worldwide audiences in 2010."},{"id":"q6","question":"Which artist is known as ''La Reina del Reggaetón'' for opening doors for women in the genre?","options":[{"id":"a","text":"Karol G","is_correct":false},{"id":"b","text":"Ivy Queen","is_correct":true},{"id":"c","text":"Natti Natasha","is_correct":false},{"id":"d","text":"Becky G","is_correct":false}],"explanation":"Ivy Queen broke through in the 1990s and opened the genre to female artists."},{"id":"q7","question":"Which 2017 song by Luis Fonsi featuring Daddy Yankee became a global phenomenon?","options":[{"id":"a","text":"''Mi Gente''","is_correct":false},{"id":"b","text":"''Felices los 4''","is_correct":false},{"id":"c","text":"''Despacito''","is_correct":true},{"id":"d","text":"''La Bicicleta''","is_correct":false}],"explanation":"''Despacito'' (2017) topped charts in dozens of countries and became a streaming landmark."},{"id":"q8","question":"Which duo, active since 1998, earned the nickname ''El Dúo de la Historia'' with hits like ''Rakata''?","options":[{"id":"a","text":"Jowell & Randy","is_correct":false},{"id":"b","text":"Alexis & Fido","is_correct":false},{"id":"c","text":"Baby Rasta & Gringo","is_correct":false},{"id":"d","text":"Wisin & Yandel","is_correct":true}],"explanation":"Wisin & Yandel, ''El Dúo de la Historia'', released ''Rakata'' on Pa''l Mundo in 2005."}]'::jsonb,
  null,
  array['music', 'trivia', 'reggaeton', 'latin music', 'urban music']::text[],
  3,
  'published',
  false,
  false,
  now()
)
