insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'es-trivia-reggaeton',
  'Trivia de reggaetón: del underground a la conquista del mundo',
  'Ocho preguntas sobre el género nacido en la escena underground de Puerto Rico que conquistó el mundo, del dembow a «Despacito».',
  'trivia',
  'easy',
  'es',
  (select id from public.categories where slug = 'music'),
  '[{"id":"q1","question":"El ritmo característico del reggaetón, el «dembow», toma su nombre de una canción de Shabba Ranks. ¿Cuál?","options":[{"id":"a","text":"«Dem Bow»","is_correct":true},{"id":"b","text":"«Ting-A-Ling»","is_correct":false},{"id":"c","text":"«Mr. Loverman»","is_correct":false},{"id":"d","text":"«Housecall»","is_correct":false}],"explanation":"El tema dancehall «Dem Bow» (1990) de Shabba Ranks aportó el patrón rítmico que el reggaetón sigue usando."},{"id":"q2","question":"¿En qué isla del Caribe tomó forma el reggaetón en la escena underground de los años noventa?","options":[{"id":"a","text":"Jamaica","is_correct":false},{"id":"b","text":"Cuba","is_correct":false},{"id":"c","text":"Puerto Rico","is_correct":true},{"id":"d","text":"República Dominicana","is_correct":false}],"explanation":"El reggaetón cristalizó en la escena underground y clubera de San Juan durante los años noventa."},{"id":"q3","question":"¿Qué país es reconocido por la escena del «reggae en español» que alimentó al reggaetón?","options":[{"id":"a","text":"Panamá","is_correct":true},{"id":"b","text":"Colombia","is_correct":false},{"id":"c","text":"Venezuela","is_correct":false},{"id":"d","text":"México","is_correct":false}],"explanation":"Artistas panameños como El General grababan reggae en español desde finales de los ochenta."},{"id":"q4","question":"¿Qué canción de Daddy Yankee abrió el reggaetón al público global en 2004?","options":[{"id":"a","text":"«Despacito»","is_correct":false},{"id":"b","text":"«Lo que pasó, pasó»","is_correct":false},{"id":"c","text":"«Rompe»","is_correct":false},{"id":"d","text":"«Gasolina»","is_correct":true}],"explanation":"«Gasolina», del álbum Barrio Fino (2004), fue el primer éxito mundial del reggaetón."},{"id":"q5","question":"¿Qué artista puertorriqueño cosechó éxitos como «Danza Kuduro» y «Dale Don Dale»?","options":[{"id":"a","text":"Don Omar","is_correct":true},{"id":"b","text":"Wisin","is_correct":false},{"id":"c","text":"Tego Calderón","is_correct":false},{"id":"d","text":"Nicky Jam","is_correct":false}],"explanation":"Don Omar, apodado «El Rey», llevó «Danza Kuduro» al público mundial en 2010."},{"id":"q6","question":"¿Qué artista es conocida como «La Reina del Reggaetón» por abrir camino a las mujeres del género?","options":[{"id":"a","text":"Karol G","is_correct":false},{"id":"b","text":"Ivy Queen","is_correct":true},{"id":"c","text":"Natti Natasha","is_correct":false},{"id":"d","text":"Becky G","is_correct":false}],"explanation":"Ivy Queen se abrió paso en los años noventa y abrió el género a las artistas mujeres."},{"id":"q7","question":"¿Qué canción de Luis Fonsi junto a Daddy Yankee, de 2017, se convirtió en un fenómeno global?","options":[{"id":"a","text":"«Mi Gente»","is_correct":false},{"id":"b","text":"«Felices los 4»","is_correct":false},{"id":"c","text":"«Despacito»","is_correct":true},{"id":"d","text":"«La bicicleta»","is_correct":false}],"explanation":"«Despacito» (2017) encabezó listas en decenas de países y marcó un hito del streaming."},{"id":"q8","question":"¿Qué dúo, activo desde 1998, recibió el apodo de «El Dúo de la Historia» con éxitos como «Rakata»?","options":[{"id":"a","text":"Jowell & Randy","is_correct":false},{"id":"b","text":"Alexis & Fido","is_correct":false},{"id":"c","text":"Baby Rasta & Gringo","is_correct":false},{"id":"d","text":"Wisin & Yandel","is_correct":true}],"explanation":"Wisin & Yandel, «El Dúo de la Historia», lanzaron «Rakata» en el álbum Pa''l Mundo (2005)."}]'::jsonb,
  null,
  array['música', 'trivia', 'reggaetón', 'música latina', 'música urbana']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-spanish-rock-trivia',
  'Rock en Español Trivia: The Anthems of the ''80s and ''90s',
  'Eight questions on the bands and albums that defined rock sung in Spanish, from Soda Stereo and Cerati to Maná and Fito Páez.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'music'),
  '[{"id":"q1","question":"Which Argentine trio, led by Gustavo Cerati, carried rock en español across Latin America?","options":[{"id":"a","text":"Enanitos Verdes","is_correct":false},{"id":"b","text":"Soda Stereo","is_correct":true},{"id":"c","text":"Los Auténticos Decadentes","is_correct":false},{"id":"d","text":"Virus","is_correct":false}],"explanation":"Soda Stereo formed in Buenos Aires in 1982 and toured the continent until 1997."},{"id":"q2","question":"Which album was Soda Stereo''s last studio record before their 1997 breakup?","options":[{"id":"a","text":"Signos","is_correct":false},{"id":"b","text":"Dynamo","is_correct":false},{"id":"c","text":"Sueño Stereo","is_correct":true},{"id":"d","text":"Doble Vida","is_correct":false}],"explanation":"Sueño Stereo (1995) closed their studio career before the farewell tour of 1997."},{"id":"q3","question":"Which Spanish band, fronted by Enrique Bunbury, recorded songs like ''Entre dos tierras''?","options":[{"id":"a","text":"Héroes del Silencio","is_correct":true},{"id":"b","text":"Radio Futura","is_correct":false},{"id":"c","text":"Mecano","is_correct":false},{"id":"d","text":"Extremoduro","is_correct":false}],"explanation":"Héroes del Silencio formed in Zaragoza and broke through with ''Entre dos tierras'' in 1990."},{"id":"q4","question":"Which Mexican band blended pop-rock with Latin sounds on hits like ''Oye mi amor''?","options":[{"id":"a","text":"Los Fabulosos Cadillacs","is_correct":false},{"id":"b","text":"Café Tacvba","is_correct":false},{"id":"c","text":"Jaguares","is_correct":false},{"id":"d","text":"Maná","is_correct":true}],"explanation":"Maná, from Guadalajara, took ''Oye mi amor'' across the Americas on their 1992 album ¿Dónde jugarán los niños?"},{"id":"q5","question":"Which Chilean trio recorded ''El baile de los que sobran'' and ''Tren al sur''?","options":[{"id":"a","text":"Los Prisioneros","is_correct":true},{"id":"b","text":"Los Tres","is_correct":false},{"id":"c","text":"Chancho en Piedra","is_correct":false},{"id":"d","text":"La Ley","is_correct":false}],"explanation":"Los Prisioneros, from San Miguel, became one of Latin America''s most influential rock bands."},{"id":"q6","question":"Which Argentine singer-songwriter released the landmark album El amor después del amor in 1992?","options":[{"id":"a","text":"Charly García","is_correct":false},{"id":"b","text":"Andrés Calamaro","is_correct":false},{"id":"c","text":"Luis Alberto Spinetta","is_correct":false},{"id":"d","text":"Fito Páez","is_correct":true}],"explanation":"El amor después del amor became one of the best-selling Argentine rock albums ever."},{"id":"q7","question":"The commercial explosion of rock en español across the Americas is generally placed in which period?","options":[{"id":"a","text":"The 1970s","is_correct":false},{"id":"b","text":"The 1980s and 1990s","is_correct":true},{"id":"c","text":"The 2000s","is_correct":false},{"id":"d","text":"The 2010s","is_correct":false}],"explanation":"The genre''s big continental boom ran from the mid-1980s through the 1990s."},{"id":"q8","question":"Which Mexican band, fronted by Saúl Hernández, recorded ''Afuera'' and ''La célula que explota''?","options":[{"id":"a","text":"Molotov","is_correct":false},{"id":"b","text":"El Tri","is_correct":false},{"id":"c","text":"Zoé","is_correct":false},{"id":"d","text":"Caifanes","is_correct":true}],"explanation":"Caifanes mixed rock with Mexican imagery on their 1990 album Caifanes II, El diablito."}]'::jsonb,
  null,
  array['music', 'trivia', 'rock en espanol', 'latin rock', 'bands']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
