values (
  'es-trivia-rock-en-espanol',
  'Trivia de rock en español: los himnos de los 80 y los 90',
  'Ocho preguntas sobre las bandas y discos que definieron el rock cantado en español, de Soda Stereo y Cerati a Maná y Fito Páez.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'music'),
  '[{"id":"q1","question":"¿Qué trío argentino, liderado por Gustavo Cerati, llevó el rock en español por toda América Latina?","options":[{"id":"a","text":"Enanitos Verdes","is_correct":false},{"id":"b","text":"Soda Stereo","is_correct":true},{"id":"c","text":"Los Auténticos Decadentes","is_correct":false},{"id":"d","text":"Virus","is_correct":false}],"explanation":"Soda Stereo se formó en Buenos Aires en 1982 y giró por el continente hasta 1997."},{"id":"q2","question":"¿Qué disco fue el último álbum de estudio de Soda Stereo antes de su separación en 1997?","options":[{"id":"a","text":"Signos","is_correct":false},{"id":"b","text":"Dynamo","is_correct":false},{"id":"c","text":"Sueño Stereo","is_correct":true},{"id":"d","text":"Doble vida","is_correct":false}],"explanation":"Sueño Stereo (1995) cerró su carrera en estudio antes de la gira de despedida de 1997."},{"id":"q3","question":"¿Qué banda española, con Enrique Bunbury al frente, grabó canciones como «Entre dos tierras»?","options":[{"id":"a","text":"Héroes del Silencio","is_correct":true},{"id":"b","text":"Radio Futura","is_correct":false},{"id":"c","text":"Mecano","is_correct":false},{"id":"d","text":"Extremoduro","is_correct":false}],"explanation":"Héroes del Silencio se formó en Zaragoza y despegó con «Entre dos tierras» en 1990."},{"id":"q4","question":"¿Qué banda mexicana mezcló el pop-rock con sonidos latinos en éxitos como «Oye mi amor»?","options":[{"id":"a","text":"Los Fabulosos Cadillacs","is_correct":false},{"id":"b","text":"Café Tacvba","is_correct":false},{"id":"c","text":"Jaguares","is_correct":false},{"id":"d","text":"Maná","is_correct":true}],"explanation":"Maná, de Guadalajara, llevó «Oye mi amor» por América con ¿Dónde jugarán los niños? (1992)."},{"id":"q5","question":"¿Qué trío chileno grabó «El baile de los que sobran» y «Tren al sur»?","options":[{"id":"a","text":"Los Prisioneros","is_correct":true},{"id":"b","text":"Los Tres","is_correct":false},{"id":"c","text":"Chancho en Piedra","is_correct":false},{"id":"d","text":"La Ley","is_correct":false}],"explanation":"Los Prisioneros, de San Miguel, se convirtieron en una de las bandas más influyentes de Latinoamérica."},{"id":"q6","question":"¿Qué cantautor argentino lanzó el disco emblemático El amor después del amor en 1992?","options":[{"id":"a","text":"Charly García","is_correct":false},{"id":"b","text":"Andrés Calamaro","is_correct":false},{"id":"c","text":"Luis Alberto Spinetta","is_correct":false},{"id":"d","text":"Fito Páez","is_correct":true}],"explanation":"El amor después del amor se convirtió en uno de los discos de rock argentino más vendidos."},{"id":"q7","question":"La explosión comercial del rock en español en América se ubica generalmente en qué época?","options":[{"id":"a","text":"Los años setenta","is_correct":false},{"id":"b","text":"Los años ochenta y noventa","is_correct":true},{"id":"c","text":"Los años dos mil","is_correct":false},{"id":"d","text":"Los años diez","is_correct":false}],"explanation":"El gran auge continental del género corrió de mediados de los ochenta a los noventa."},{"id":"q8","question":"¿Qué banda mexicana, con Saúl Hernández al frente, grabó «Afuera» y «La célula que explota»?","options":[{"id":"a","text":"Molotov","is_correct":false},{"id":"b","text":"El Tri","is_correct":false},{"id":"c","text":"Zoé","is_correct":false},{"id":"d","text":"Caifanes","is_correct":true}],"explanation":"Caifanes mezcló rock con imaginario mexicano en su disco de 1990 Caifanes II, El diablito."}]'::jsonb,
  null,
  array['música', 'trivia', 'rock en español', 'rock latino', 'bandas']::text[],
  3,
  'published',
  false,
  false,
  now()
)
