insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-movie-soundtracks-trivia',
  'Movie Soundtracks Trivia: The Music Behind the Movies',
  'Eight questions on the composers and themes that made cinema sound legendary, from the two notes of Jaws to Hans Zimmer''s epics.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'music'),
  '[{"id":"q1","question":"The famous two-note motif in Jaws (1975) was written by which composer?","options":[{"id":"a","text":"Bernard Herrmann","is_correct":false},{"id":"b","text":"John Williams","is_correct":true},{"id":"c","text":"Jerry Goldsmith","is_correct":false},{"id":"d","text":"Elmer Bernstein","is_correct":false}],"explanation":"John Williams'' alternating E and F notes became the sound of looming danger."},{"id":"q2","question":"The theme of which Star Wars villain is known as ''The Imperial March''?","options":[{"id":"a","text":"Darth Vader","is_correct":true},{"id":"b","text":"Emperor Palpatine","is_correct":false},{"id":"c","text":"Grand Moff Tarkin","is_correct":false},{"id":"d","text":"Boba Fett","is_correct":false}],"explanation":"John Williams wrote the Imperial March for Darth Vader in The Empire Strikes Back (1980)."},{"id":"q3","question":"Which Italian composer scored Sergio Leone''s spaghetti westerns, including The Good, the Bad and the Ugly?","options":[{"id":"a","text":"Nino Rota","is_correct":false},{"id":"b","text":"Riz Ortolani","is_correct":false},{"id":"c","text":"Angelo Badalamenti","is_correct":false},{"id":"d","text":"Ennio Morricone","is_correct":true}],"explanation":"Morricone''s whistled themes and electric guitars defined the spaghetti western sound."},{"id":"q4","question":"Which German composer scored Gladiator, The Lion King and Inception?","options":[{"id":"a","text":"Hans Zimmer","is_correct":true},{"id":"b","text":"James Horner","is_correct":false},{"id":"c","text":"Howard Shore","is_correct":false},{"id":"d","text":"Alan Silvestri","is_correct":false}],"explanation":"Hans Zimmer won his first Oscar for The Lion King (1994) and scored Gladiator in 2000."},{"id":"q5","question":"Bernard Herrmann used only string instruments for the shrieking score of which Hitchcock film?","options":[{"id":"a","text":"Vertigo","is_correct":false},{"id":"b","text":"The Birds","is_correct":false},{"id":"c","text":"North by Northwest","is_correct":false},{"id":"d","text":"Psycho","is_correct":true}],"explanation":"The all-strings score of Psycho (1960) made the shower scene unforgettable."},{"id":"q6","question":"In film music, what is a ''leitmotif''?","options":[{"id":"a","text":"A recurring theme tied to a character or idea","is_correct":true},{"id":"b","text":"A song used for marketing the film","is_correct":false},{"id":"c","text":"Music heard only during the credits","is_correct":false},{"id":"d","text":"A melody played just once in the film","is_correct":false}],"explanation":"A leitmotif is a short musical theme that returns with a character, place or idea."},{"id":"q7","question":"Which composer wrote the score for Titanic (1997), including ''My Heart Will Go On''?","options":[{"id":"a","text":"Hans Zimmer","is_correct":false},{"id":"b","text":"Alan Silvestri","is_correct":false},{"id":"c","text":"James Horner","is_correct":true},{"id":"d","text":"Danny Elfman","is_correct":false}],"explanation":"James Horner''s Titanic score and its Céline Dion theme won two Oscars in 1998."},{"id":"q8","question":"Which composer created the electronic soundscape of Blade Runner (1982) and the theme of Chariots of Fire?","options":[{"id":"a","text":"Tangerine Dream","is_correct":false},{"id":"b","text":"Giorgio Moroder","is_correct":false},{"id":"c","text":"Jean-Michel Jarre","is_correct":false},{"id":"d","text":"Vangelis","is_correct":true}],"explanation":"Vangelis won an Oscar for Chariots of Fire (1981) and scored Blade Runner the next year."}]'::jsonb,
  null,
  array['music', 'trivia', 'soundtracks', 'film music', 'composers']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'es-trivia-bandas-sonoras',
  'Trivia de bandas sonoras: la música detrás del cine',
  'Ocho preguntas sobre los compositores y temas que hicieron sonar la leyenda del cine, de las dos notas de Tiburón a los épicos de Hans Zimmer.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'music'),
  '[{"id":"q1","question":"¿Qué compositor escribió el famoso motivo de dos notas de Tiburón (1975)?","options":[{"id":"a","text":"Bernard Herrmann","is_correct":false},{"id":"b","text":"John Williams","is_correct":true},{"id":"c","text":"Jerry Goldsmith","is_correct":false},{"id":"d","text":"Elmer Bernstein","is_correct":false}],"explanation":"Las notas alternas mi y fa de John Williams se convirtieron en el sonido del peligro inminente."},{"id":"q2","question":"El tema de qué villano de Star Wars es conocido como «La marcha imperial»?","options":[{"id":"a","text":"Darth Vader","is_correct":true},{"id":"b","text":"El emperador Palpatine","is_correct":false},{"id":"c","text":"El gran moff Tarkin","is_correct":false},{"id":"d","text":"Boba Fett","is_correct":false}],"explanation":"John Williams compuso la Marcha Imperial para Darth Vader en El imperio contraataca (1980)."},{"id":"q3","question":"¿Qué compositor italiano firmó las bandas sonoras de los spaghetti westerns de Sergio Leone, como El bueno, el feo y el malo?","options":[{"id":"a","text":"Nino Rota","is_correct":false},{"id":"b","text":"Riz Ortolani","is_correct":false},{"id":"c","text":"Angelo Badalamenti","is_correct":false},{"id":"d","text":"Ennio Morricone","is_correct":true}],"explanation":"Los silbidos y las guitarras eléctricas de Morricone definieron el sonido del spaghetti western."},{"id":"q4","question":"¿Qué compositor alemán firmó las partituras de Gladiator, El rey león e Inception?","options":[{"id":"a","text":"Hans Zimmer","is_correct":true},{"id":"b","text":"James Horner","is_correct":false},{"id":"c","text":"Howard Shore","is_correct":false},{"id":"d","text":"Alan Silvestri","is_correct":false}],"explanation":"Hans Zimmer ganó su primer Oscar por El rey león (1994) y compuso Gladiator en 2000."},{"id":"q5","question":"Bernard Herrmann usó solo instrumentos de cuerda en la estridente partitura de qué película de Hitchcock?","options":[{"id":"a","text":"Vértigo","is_correct":false},{"id":"b","text":"Los pájaros","is_correct":false},{"id":"c","text":"Con la muerte en los talones","is_correct":false},{"id":"d","text":"Psicosis","is_correct":true}],"explanation":"La partitura de solo cuerdas de Psicosis (1960) hizo inolvidable la escena de la ducha."},{"id":"q6","question":"En la música de cine, ¿qué es un «leitmotiv»?","options":[{"id":"a","text":"Un tema recurrente asociado a un personaje o idea","is_correct":true},{"id":"b","text":"Una canción usada para promocionar la película","is_correct":false},{"id":"c","text":"La música que suena solo durante los créditos","is_correct":false},{"id":"d","text":"Una melodía que se escucha una sola vez","is_correct":false}],"explanation":"Un leitmotiv es un tema breve que regresa con un personaje, lugar o idea."},{"id":"q7","question":"¿Qué compositor firmó la partitura de Titanic (1997), que incluía «My Heart Will Go On»?","options":[{"id":"a","text":"Hans Zimmer","is_correct":false},{"id":"b","text":"Alan Silvestri","is_correct":false},{"id":"c","text":"James Horner","is_correct":true},{"id":"d","text":"Danny Elfman","is_correct":false}],"explanation":"La partitura de James Horner y el tema de Céline Dion ganaron dos Oscar en 1998."},{"id":"q8","question":"¿Qué compositor creó el paisaje sonoro electrónico de Blade Runner (1982) y el tema de Carros de fuego?","options":[{"id":"a","text":"Tangerine Dream","is_correct":false},{"id":"b","text":"Giorgio Moroder","is_correct":false},{"id":"c","text":"Jean-Michel Jarre","is_correct":false},{"id":"d","text":"Vangelis","is_correct":true}],"explanation":"Vangelis ganó un Oscar por Carros de fuego (1981) y compuso Blade Runner al año siguiente."}]'::jsonb,
  null,
  array['música', 'trivia', 'bandas sonoras', 'música de cine', 'compositores']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

